select 
from rail_general_item

    del_flag = '0'
    and item_type = #{itemType}
    and item_title like concat('%', #{itemTitle}, '%')
    and project_id = #{projectId}
    and project_name like concat('%', #{projectName}, '%')
    and line_name like concat('%', #{lineName}, '%')
    and severity_level = #{severityLevel}
    and priority = #{priority}
    and status = #{status}
    and responsible_user_id = #{responsibleUserId}
    and create_by = #{createBy}

        and (item_title like concat('%', #{keyword}, '%') or item_content like concat('%', #{keyword}, '%') or location_desc like concat('%', #{keyword}, '%'))


order by occur_time desc, update_time desc, item_id desc

